+  <body>
+    <main class="page-shell">
+      <section class="support-card" aria-labelledby="support-title">
+        <p class="eyebrow">Support request</p>
+        <h1 id="support-title">How can we help?</h1>
+        <p class="intro">
+          Tell our support team how to reach you. We will use your contact
+          details only to follow up on this request.
+        </p>
+        <div id="app"></div>
+      </section>
+    </main>
+
+    <script>
+      const fields = [
+        {
+          id: "fullName",
+          label: "Full name",
+          type: "text",
+          autocomplete: "name",
+          required: true,
+          validate(value) {
+            return value.trim() ? "" : "Enter your full name.";
+          },
+        },
+        {
+          id: "email",
+          label: "Email address",
+          type: "email",
+          autocomplete: "email",
+          required: true,
+          validate(value) {
+            const trimmedValue = value.trim();
+            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+            if (!trimmedValue) {
+              return "Enter your email address.";
+            }
+
+            return emailPattern.test(trimmedValue)
+              ? ""
+              : "Enter a valid email address, such as name@example.com.";
+          },
+        },
+        {
+          id: "phone",
+          label: "Phone number",
+          type: "tel",
+          autocomplete: "tel",
+          required: false,
+          helperText: "Use 10 to 15 digits, with optional spaces, dashes, parentheses, or a leading plus sign.",
+          validate(value) {
+            const trimmedValue = value.trim();
+            const phonePattern = /^\+?[0-9\s().-]{10,20}$/;
+            const digitsOnly = trimmedValue.replace(/\D/g, "");
+
+            if (!trimmedValue) {
+              return "";
+            }
+
+            return phonePattern.test(trimmedValue) && digitsOnly.length >= 10 && digitsOnly.length <= 15
+              ? ""
+              : "Enter a valid phone number using 10 to 15 digits.";
+          },
+        },
+      ];
+
+      const state = {
+        values: {
+          fullName: "",
+          email: "",
+          phone: "",
+        },
+        errors: {},
+        submitted: false,
+      };
+
+      function Field({ field }) {
+        const error = state.errors[field.id] || "";
+        const helperId = `${field.id}-helper`;
+        const errorId = `${field.id}-error`;
+        const describedBy = [field.helperText ? helperId : "", error ? errorId : ""]
+          .filter(Boolean)
+          .join(" ");
+
+        return `
+          <div class="form-field">
+            <label for="${field.id}">
+              ${field.label}
+              ${field.required ? '<span class="required-note">(required)</span>' : '<span class="required-note">(optional)</span>'}
+            </label>
+            <input
+              id="${field.id}"
+              name="${field.id}"
+              type="${field.type}"
+              value="${escapeHtml(state.values[field.id])}"
+              autocomplete="${field.autocomplete}"
+              ${field.required ? "required" : ""}
+              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
+              aria-invalid="${error ? "true" : "false"}"
+            >
+            ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
+            ${error ? `<p class="error-message" id="${errorId}">${error}</p>` : ""}
+          </div>
+        `;
+      }
+
+      function ContactForm() {
+        const successMessage = state.submitted && !Object.keys(state.errors).length
+          ? '<p class="success-message" role="status">Thanks. Your support contact details are ready to send.</p>'
+          : "";
+
+        return `
+          <form id="support-form" novalidate>
+            ${fields.map((field) => Field({ field })).join("")}
+            ${successMessage}
+            <button type="submit">Submit request</button>
+          </form>
+        `;
+      }
+
+      function validateForm() {
+        state.errors = fields.reduce((errors, field) => {
+          const error = field.validate(state.values[field.id]);
+
+          if (error) {
+            errors[field.id] = error;
+          }
+
+          return errors;
+        }, {});
+
+        return state.errors;
+      }
+
+      function render() {
+        document.querySelector("#app").innerHTML = ContactForm();
+        bindEvents();
+      }
+
+      function bindEvents() {
+        const form = document.querySelector("#support-form");
+
+        fields.forEach((field) => {
+          const input = document.querySelector(`#${field.id}`);
+
+          input.addEventListener("input", (event) => {
+            state.values[field.id] = event.target.value;
+
+            if (state.errors[field.id]) {
+              const error = field.validate(state.values[field.id]);
+
+              if (error) {
+                state.errors[field.id] = error;
+              } else {
+                delete state.errors[field.id];
+              }
+
+              render();
+              document.querySelector(`#${field.id}`).focus();
+            }
+          });
+
+          input.addEventListener("blur", () => {
+            const error = field.validate(state.values[field.id]);
+
+            if (error) {
+              state.errors[field.id] = error;
+            } else {
+              delete state.errors[field.id];
+            }
+
+            render();
+          });
+        });
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+          state.submitted = true;
+          validateForm();
+          render();
+
+          const firstInvalidField = fields.find((field) => state.errors[field.id]);
+
+          if (firstInvalidField) {
+            document.querySelector(`#${firstInvalidField.id}`).focus();
+          }
+        });
+      }
+
+      function escapeHtml(value) {
+        return value
+          .replaceAll("&", "&amp;")
+          .replaceAll('"', "&quot;")
+          .replaceAll("<", "&lt;")
+          .replaceAll(">", "&gt;");
+      }
+
+      render();
+    </script>
